import sqlite3,json,hashlib
c=sqlite3.connect('file:/data/app.db?mode=ro',uri=True)
result={}
for name in ('users','products'):
 rows=c.execute('SELECT * FROM '+name+' ORDER BY id').fetchall()
 result[name]={'count':len(rows),'sha256':hashlib.sha256(json.dumps(rows,default=str).encode()).hexdigest()}
print(json.dumps(result))
